import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import * as roomsService from '../rooms/service.js';
import { isBefore, MINUTE_IN_MS, parseInstant } from '../../shared/time.js';
import * as repository from './repository.js';
import { BOOKING_CANCELLED } from './schema.js';
import type {
  AvailabilityInput,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

export interface TimeSlot {
  startsAt: Date;
  endsAt: Date;
}

const SUGGESTION_HORIZON_MS = 7 * 24 * 60 * 60 * 1000;
const MAX_SUGGESTIONS = 3;
const DEFAULT_AVAILABILITY_DURATION_MINUTES = 30;

function computeGaps(bookings: Booking[], from: Date, to: Date, durationMs: number): TimeSlot[] {
  const gaps: TimeSlot[] = [];
  let cursor = from;
  for (const booking of bookings) {
    const gapEnd = booking.startsAt.getTime() > cursor.getTime() ? booking.startsAt : cursor;
    if (gapEnd.getTime() - cursor.getTime() >= durationMs) {
      gaps.push({ startsAt: cursor, endsAt: gapEnd });
    }
    if (booking.endsAt.getTime() > cursor.getTime()) {
      cursor = booking.endsAt;
    }
  }
  if (to.getTime() - cursor.getTime() >= durationMs) {
    gaps.push({ startsAt: cursor, endsAt: to });
  }
  return gaps;
}

async function suggestSlots(roomId: string, from: Date, durationMs: number): Promise<TimeSlot[]> {
  const to = new Date(from.getTime() + SUGGESTION_HORIZON_MS);
  const bookings = await repository.findActiveInRange(roomId, from, to);
  const gaps = computeGaps(bookings, from, to, durationMs);
  return gaps
    .slice(0, MAX_SUGGESTIONS)
    .map((gap) => ({ startsAt: gap.startsAt, endsAt: new Date(gap.startsAt.getTime() + durationMs) }));
}

async function assertNoConflict(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<void> {
  const conflict = await repository.findOverlapping(roomId, startsAt, endsAt, excludeId);
